using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CustodySuccessionTests
{
    static readonly EntityId Player=new("person:shingen"),Ward=new("created:ward"),Heir=HistoricalHouseholdCatalog.Edition.People.Single().Id,Owner=new("org:takeda"),Receiver=new("org:oda");
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.Code+":"+r.VisibleReason);
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static void Move(WorldSession s,string node){Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:succ-custody-move/"+s.Revision,node),s.Revision));At(s,s.Seconds+2);At(s,s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==Player).Legs[^1].EndAt+1);}
    static WorldSession Start(ulong seed,string? routine=null){var p=NewGameWorldTests.Officer(Ward.Value,StartTemplate.Retainer,lord:Player.Value) with{BirthYear=1520};var records=NewGameWorld.Normalize([p]);var raw=NewGameWorld.Scenario(HistoricalStartCatalog.Current);var request=new WorldSetupRequest(records,[]);var setup=NewGameSetup.Confirm(raw,request,NewGameSetup.Preview(raw,request));return new(NewGameWorld.Create(setup,records,Player.Value,seed,historicalCatalog:HistoricalStartCatalog.Current,npcRoutinePolicy:routine,demandPolicy:routine==NewGameNpcRoutine.ContinuingPolicy?LocalWorkDemand.Policy:null,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,worldArmyPolicy:NpcArmies.CompactCombatPolicy,economyPolicy:HouseSuccession.Policy,companionPolicy:PersonalCompanions.Policy,socialPolicy:CharacterRelations.Policy,custodyPolicy:HostageCustody.Policy));}
    static readonly Lazy<ulong> Seed=new(()=>{for(ulong n=1;n<100;n++){var w=Start(n).DiagnosticSnapshot();if(CharacterRelations.DiagnosticTrait(w,Ward,SocialTrait.Duty)+CharacterRelations.DiagnosticTrait(w,Ward,SocialTrait.Affection)>=80&&CharacterRelations.AcceptsCompanion(w,Heir,20,0,1))return n;}throw new Exception("No fixture seed");});
    static EntityId Root(WorldSession s)=>s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;
    static CommandResult Act(WorldSession s,CustodyAction a,string? id=null)=>s.ManageCustody(new(new(id??"request:custody-successor/"+s.Revision),a,Original:Root(s)),Player,s.Revision);
    internal static WorldSession Held(string? routine=null){var s=Start(Seed.Value,routine);Move(s,"castle");Good(s.ManageCustody(new(new("request:succ-custody"),CustodyAction.Propose,Ward,Receiver,Days:7,Guarantee:"当主交代後も本人と保証を保持"),Player,s.Revision));At(s,s.Seconds+1);Good(Act(s,CustodyAction.Admit));return s;}
    internal static WorldSession Succeeded(bool travel=true){var s=Held();Move(s,"kofu");var id=new EntityId("request:head-custody-succession");Good(s.ManageHouseSuccession(new(id,HouseSuccessionAction.Nominate,Owner,Heir),Player,s.Revision));Good(s.ManageHouseSuccession(new(new("request:head-custody-confirm"),HouseSuccessionAction.Confirm,Owner,Original:id),Player,s.Revision));At(s,s.Seconds+2);if(travel){Good(s.ManageCompanion(new(new("request:heir-custody-visit"),Heir,CompanionAction.VisitCustodySite,Destination:"castle"),Player,s.Revision));At(s,s.Seconds+2);}Assert.Equal(Heir,HouseSuccession.Head(s.DiagnosticSnapshot(),Owner));if(travel){At(s,s.DiagnosticSnapshot().Branches!.Journeys.Max(j=>j.Legs[^1].EndAt)+1);Assert.Equal(new EntityId("site:castle"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Heir).Site);}return s;}
    [Fact]public void ActualSuccessionRequiresSeparateLocalReconfirmation(){var s=Succeeded();var original=ContractJson.Write(s.DiagnosticSnapshot().Custody!.Entries.First());Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Release).Code);Good(Act(s,CustodyAction.Reconfirm));Assert.Equal(original,ContractJson.Write(s.DiagnosticSnapshot().Custody!.Entries.First()));Assert.Equal(Heir,s.DiagnosticSnapshot().Custody!.Entries.Last().Representatives!.Guardian);Good(Act(s,CustodyAction.Release));Assert.False(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void NoRepresentativeChangeCannotBeReconfirmed(){var s=Held();Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Reconfirm).Code);}
    [Fact]public void AbsentOriginalAndSuccessorCannotReleaseRemotely(){var s=Succeeded(false);Assert.False(HostageCustody.View(s.DiagnosticSnapshot()).Single().CanReconfirm);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Reconfirm).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Release).Code);}
    [Fact]public void ReconfirmationIsIdempotentAndDoesNotExtendExpiry(){var s=Succeeded();var before=s.DiagnosticSnapshot().Custody!.Entries.First().Terms!;Good(Act(s,CustodyAction.Reconfirm,"request:reconfirm-once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CustodyAction.Reconfirm,"request:reconfirm-once").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Reconfirm).Code);Assert.Equal(before,s.DiagnosticSnapshot().Custody!.Entries.First().Terms);}
    [Fact]public void CurrentWillingnessInputBlocksVisit(){var s=Succeeded(false);var w=s.DiagnosticSnapshot();Assert.True(HostageCustody.CanVisit(w,Heir,"castle",s.Seconds,s.Revision+1));w.Characters=w.Characters.Select(c=>c.Id==Heir?c with{WillObey=false}:c).ToArray();Assert.False(HostageCustody.CanVisit(w,Heir,"castle",s.Seconds,s.Revision+1));}
    [Fact]public void VisitCannotBeUsedForArbitraryDestinations(){var s=Succeeded(false);Assert.Equal(ResultCode.NotAvailable,s.ManageCompanion(new(new("request:wrong-custody-site"),Heir,CompanionAction.VisitCustodySite,Destination:"fork"),Player,s.Revision).Code);}
    [Fact]public void VisitDoesNotCreateAnEmploymentOrChargeMoney(){var s=Succeeded();Assert.DoesNotContain(s.DiagnosticSnapshot().Companions!.Orders,q=>q.Input.Action==CompanionAction.Agree);Assert.All(s.DiagnosticSnapshot().Companions!.Orders,q=>Assert.Equal(0,q.Input.Amount));}
    [Fact]public void ReleasedOriginalCannotAuthorizeAnotherVisit(){var s=Succeeded();Good(Act(s,CustodyAction.Reconfirm));Good(Act(s,CustodyAction.Release));Assert.Empty(HostageCustody.Visits(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Reconfirm).Code);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)]public void ActualRecoveryKeepsReconfirmedOriginalAndFuture(int phase){var s=Succeeded();if(phase>0)Good(Act(s,CustodyAction.Reconfirm));if(phase>1)Good(Act(s,CustodyAction.Release));s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"custody-succession-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"case",w.WorldId).Published);var host=new WorldSessionHost(Start(Seed.Value));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(HostageCustody.View(w)),ContractJson.Write(HostageCustody.View(host.Current.DiagnosticSnapshot())));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,$"custody-succession-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"custody-succession-{phase}.restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
}
